targets.expr:
(
    (
        sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$"}) by (instance)
        + (
            sum(http_server_request_duration_seconds_bucket{le="$tolerated", http_response_status_code=~"^2..$"}) by (instance)
            - sum(http_server_request_duration_seconds_bucket{le="$target", http_response_status_code=~"^2..$"}) by (instance)
        ) / 2
    ) / sum(http_server_request_duration_seconds_count{job=~"$job", http_response_status_code=~"^2..$"}) by (instance)
) * 100
